<template><div>    <div>
     <a-alert v-if="form.order_state==='cancelled'" type="warning" show-icon message="订单已取消并停产。保留历史日报、质检、成品入库和退料记录，不再新增生产或领补料。"/>
     <a-alert v-else-if="(form.orderChanges||[]).some(c=>c.workflow_status==='approved')" type="warning" show-icon message="订单变更已批准，待生产统筹落实计划后再继续生产。"/>
     <h3>实际开工与生产日报</h3><p>数量单位：吨。各工序分别累计产出；最终成品仍需质检和入库。</p>
     <table class="details"><thead><tr><th>产品 / 工序 / 车间</th><th>分配量</th><th>实际开工</th><th>累计产出</th><th>操作</th></tr></thead><tbody><tr v-for="r in executionRoutes" :key="r.key"><td>{{product(form.lines[r.lineNo])}} / 工序{{r.stageNo}} / {{workshops[r.workshopNo-1]}}</td><td>{{r.quantity}}</td><td>{{r.start?date(r.start.actual_start):'未开工'}}</td><td>{{r.output}}</td><td><a v-if="!readOnly && r.workshopNo===myWorkshop && (form.workshops||[]).some(w=>w.workshop_no===myWorkshop && w.workflow_status==='scheduled')" @click="openExecution(r)">{{r.start?'录生产日报':'确认开工'}}</a></td></tr></tbody></table>
     <h3>日报记录</h3><p>本车间主任可直接更正未送检的日报，原因必填；已送检、交接或成品入库的批次不能直接更正。</p><div class="table-scroll"><table class="details"><thead><tr><th>日期</th><th>产品 / 工序 / 车间</th><th>批号</th><th>投入</th><th>产出</th><th>损耗</th><th>录入人</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="r in form.reports" :key="r.id"><td>{{r.report_date}}</td><td>{{product(form.lines[r.line_no])}} / {{r.stage_no}} / {{workshops[r.workshop_no-1]}}</td><td>{{r.batch_number}}</td><td>{{r.input_quantity}}</td><td>{{r.output_quantity}}</td><td>{{r.loss_quantity}}</td><td>{{r.actor_name}}</td><td>{{r.comment}}</td><td><template v-if="!readOnly&&(options.workshopNos||[]).includes(r.workshop_no)"><span v-if="reportLocked(r)">已送检，不能更正</span><a v-else @click="correctReport(r)">更正日报</a><br></template><a @click="historyReport=r.id;historyVisible=true">更正记录</a></td></tr></tbody></table></div>
    </div>  <j-modal fullscreen switchFullscreen :ok-close="false" cancel-text="退出" :title="execution.action==='start'?'确认实际开工':execution.action==='correctReport'?'直接更正生产日报':'录生产日报'" :visible="executionVisible" :confirm-loading="saving" @cancel="executionVisible=false" @ok="saveExecution">
   <template v-if="execution.action==='start'"><div class="label">实际开工时间</div><a-input type="datetime-local" v-model="execution.actualStart"/><a-checkbox v-model="execution.materialsReady" style="margin-top:12px">已核对本产品工序原料齐套，可以开工</a-checkbox></template>
   <template v-else><div class="label">日报日期</div><a-input type="date" v-model="execution.reportDate"/><div class="label">批号</div><a-select v-if="execution.stageNo>1" v-model="execution.batchNumber" show-search style="width:100%" placeholder="选择已确认接收的半成品批次"><a-select-option v-for="batch in receivedBatches" :key="batch.batchNumber" :value="batch.batchNumber" :disabled="batch.available<=0">{{batch.batchNumber}} / 剩余可投入 {{batch.available}} 吨</a-select-option></a-select><a-input v-else v-model="execution.batchNumber" :max-length="100" placeholder="填写本次新生产批号"/><p v-if="execution.stageNo>1">{{selectedBatch?'该批已接收 '+selectedBatch.received+' 吨，其他日报已投入 '+selectedBatch.used+' 吨，本次最多可投入 '+selectedBatch.available+' 吨。':'请先选择已接收批次；没有可用批次时，请核对上一工序交接和本车间接收记录。'}}</p><div v-for="f in [['inputQuantity','投入量'],['outputQuantity','产出量'],['lossQuantity','损耗量']]" :key="f[0]"><div class="label">{{f[1]}}（吨）</div><a-input-number v-model="execution[f[0]]" :max="f[0]==='inputQuantity'&&execution.stageNo>1?(selectedBatch?selectedBatch.available:0):undefined" :min="0" :precision="6" style="width:100%"/></div></template>
   <div class="label">备注</div><a-textarea v-model="execution.comment" :max-length="2000"/>
   <template v-if="execution.action==='correctReport'"><div class="label">更正原因（必填，无需审批）</div><a-textarea v-model="execution.reason" :max-length="2000"/></template>
  </j-modal>
  <j-modal fullscreen switchFullscreen title="日报更正记录" :visible="historyVisible" :width="1100" :footer="null" @cancel="historyVisible=false">
   <p v-if="!corrections.length">该日报暂无更正记录。</p>
   <div v-for="(h,i) in corrections" :key="i"><p>{{date(h.created_at)}}　{{h.actor_name}}　原因：{{h.change.reason}}</p><div class="table-scroll"><table class="details"><thead><tr><th>内容</th><th>日报日期</th><th>批号</th><th>投入（吨）</th><th>产出（吨）</th><th>损耗（吨）</th><th>备注</th></tr></thead><tbody><tr v-for="k in ['before','after']" :key="k"><td>{{k==='before'?'更正前':'更正后'}}</td><td>{{String(h.change[k].report_date).slice(0,10)}}</td><td>{{h.change[k].batch_number}}</td><td>{{h.change[k].input_quantity}}</td><td>{{h.change[k].output_quantity}}</td><td>{{h.change[k].loss_quantity}}</td><td>{{h.change[k].comment}}</td></tr></tbody></table></div></div>
  </j-modal>
</div></template>
<script>
import {getAction,postAction} from '@/api/manage'
export default {
 props:{task:{type:Object,required:true},options:{type:Object,required:true},readOnly:{type:Boolean,default:false}},
 data(){return {form:this.task,execution:{},executionVisible:false,saving:false,historyVisible:false,historyReport:null,workshops:['一车间','二车间','三车间']}},
 watch:{task(value){this.form=value}},
 computed:{receivedBatches(){return (this.form.receivedBatches||[]).filter(b=>b.line_no===this.execution.lineNo&&b.stage_no===this.execution.stageNo&&b.workshop_no===this.execution.workshopNo).map(b=>{const used=(this.form.reports||[]).filter(r=>r.line_no===b.line_no&&r.stage_no===b.stage_no&&r.workshop_no===b.workshop_no&&r.batch_number===b.batch_number&&r.id!==this.execution.reportId).reduce((sum,r)=>sum+Number(r.input_quantity),0);return {batchNumber:b.batch_number,received:Number(b.received),used:Number(used.toFixed(6)),available:Math.max(0,Number((Number(b.received)-used).toFixed(6)))}})},selectedBatch(){return this.receivedBatches.find(b=>b.batchNumber===this.execution.batchNumber)},corrections(){return (this.form.history||[]).filter(h=>h.action==='report_correct').map(h=>({...h,change:JSON.parse(h.payload_json)})).filter(h=>h.change.reportId===this.historyReport)},myWorkshop(){return (this.options.workshopNos||[])[0]},executionRoutes(){const result={};for(const r of this.form.routes||[]){const key=[r.lineNo,r.stageNo,r.workshopNo].join('|');if(!result[key])result[key]={...r,key,quantity:0,output:0,start:(this.form.starts||[]).find(x=>x.line_no===r.lineNo && x.stage_no===r.stageNo && x.workshop_no===r.workshopNo)};result[key].quantity+=Number(r.quantity)}for(const r of this.form.reports||[]){const item=result[[r.line_no,r.stage_no,r.workshop_no].join('|')];if(item)item.output+=Number(r.output_quantity)}return Object.values(result)}},
 methods:{
 reportLocked(r){return (this.form.reportLocks||[]).some(l=>l.line_no===r.line_no&&l.stage_no===r.stage_no&&l.batch_number===r.batch_number&&(l.workshop_no===r.workshop_no||l.inspection_kind==='finished'))},
 correctReport(r){this.execution={action:'correctReport',reportId:r.id,lineNo:r.line_no,stageNo:r.stage_no,workshopNo:r.workshop_no,reportDate:String(r.report_date).slice(0,10),batchNumber:r.batch_number,inputQuantity:r.input_quantity,outputQuantity:r.output_quantity,lossQuantity:r.loss_quantity,comment:r.comment,reason:''};this.executionVisible=true},
 async request(path,body){const r=body===undefined?await getAction('/factoryProduction'+path):await postAction('/factoryProduction'+path,body);if(r.code!==200)throw new Error(r.message||(r.data&&r.data.message)||'操作失败');return r.data},
 product(line){return line?[line.name,line.brand,line.standard,line.model].filter(Boolean).join(' / '):''},
 date(value){return value?new Date(value).toLocaleString('zh-CN'):''},error(e){this.$message.error(e.message||'请求失败')},
  openExecution(r){const now=new Date();const local=new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString();this.execution={action:r.start?'report':'start',lineNo:r.lineNo,stageNo:r.stageNo,workshopNo:r.workshopNo,actualStart:local.slice(0,16),materialsReady:false,reportDate:local.slice(0,10),batchNumber:'',inputQuantity:null,outputQuantity:null,lossQuantity:0,comment:''};if(r.stageNo>1){const batches=this.receivedBatches.filter(b=>b.available>0);if(batches.length===1)this.execution.batchNumber=batches[0].batchNumber}this.executionVisible=true},
  async saveExecution(){this.saving=true;try{if(this.execution.action!=='start'&&this.execution.stageNo>1&&(!this.selectedBatch||!(Number(this.execution.inputQuantity)>0)||Number(this.execution.inputQuantity)>this.selectedBatch.available))throw new Error('请选择已接收批次，投入数量须大于0且不能超过该批剩余可投入数量');if(this.execution.action==='correctReport'&&!this.execution.reason.trim())throw new Error('请填写更正原因');await this.request('/'+this.form.head_id+'/execution',{...this.execution,version:this.form.version});this.form=await this.request('/'+this.form.head_id);this.executionVisible=false;this.$message.success('生产记录已保存');this.$emit('saved')}catch(e){this.error(e)}finally{this.saving=false}},

}
}
</script>
<style scoped>.label{margin:12px 0 6px}h3{margin:22px 0 12px}.table-scroll{overflow-x:auto}.details{border-collapse:collapse;width:100%}.details th,.details td{border:1px solid #e8e8e8;padding:9px;text-align:left}.details th{background:#fafafa}</style>
